import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 270005;
    static int n, m, k, mod;
    static int[][] f = new int[19][MAXN];
    static List<Long> g = new ArrayList<>();
    static int[] cnt = new int[MAXN];

    static int modify(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void combine(IntWrapper x, int y) {
        x.value = modify(x.value + y);
    }

    static int fast_pow(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) res = (int)((long)res * base % mod);
            base = (int)((long)base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static int[] fact = new int[MAXN];
    static int[] inv_fact = new int[MAXN];

    static void prepare(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % mod);
        }
        inv_fact[n] = fast_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (int)((long)inv_fact[i + 1] * (i + 1) % mod);
        }
    }

    static void transform(int[] arr, int size, int h) {
        for (int p = 1; p < size; p <<= 1) {
            for (int i = 0; i < size; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    combine(new IntWrapper(arr[k + p]), h * arr[k]);
                    arr[k + p] = ((IntWrapper) (new IntWrapper(arr[k + p]))).value;
                }
            }
        }
    }

    static class IntWrapper {
        int value;
        IntWrapper(int v) { value = v; }
    }

    static List<Long> series_power(List<Long> A, int k) {
        List<Long> C = new ArrayList<>(Collections.nCopies(g.size(), 0L));
        C.set(0, 1L);
        List<Long> base = new ArrayList<>(A);
        while (k != 0) {
            if ((k & 1) != 0) {
                C = multiplySeries(C, base);
            }
            base = multiplySeries(base, base);
            k >>= 1;
        }
        return C;
    }

    static List<Long> multiplySeries(List<Long> A, List<Long> B) {
        int size = g.size() - 1;
        List<Long> C = new ArrayList<>(Collections.nCopies(size + 1, 0L));
        for (int i = 0; i <= size; i++) {
            for (int j = 0; j <= size - i; j++) {
                C.set(i + j, C.get(i + j) + A.get(i) * B.get(j));
            }
        }
        for (int i = 0; i <= size; i++) {
            C.set(i, C.get(i) % mod);
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        prepare(n);
        if ((n & 1) == 1) {
            System.out.println(fast_pow(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        int l = 0;
        while ((1 << l) < m) l++;
        for (int i = 0; i < m; i++) {
            cnt[i] = Integer.bitCount(i);
        }
        prepare(m);
        for (int i = 0; i < m; i++) {
            f[cnt[i]][i] = inv_fact[i];
        }
        for (int i = 0; i < l; i++) {
            transform(f[i], m, 1);
        }
        g = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long)f[i][s]);
            }
            g = series_power(g, k);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }
        transform(f[cnt[n]], m, -1);
        int result = modify(fast_pow(k, n) - (int)((long)f[cnt[n]][n] * fact[n] % mod));
        System.out.println(result);
    }
}
